PHP 8.0+ / Guzzle 7 composer require erikwang2013/bigdata-php use Erikwang2013\BigData\BigData;

$trino = BigData::driver('trino', [
    'host' => '127.0.0.1',
    'port' => 8080,
    'user' => 'php',
    'catalog' => 'hive',
    'schema' => 'default',
]);

$result = $trino->query('SELECT 1 AS id');

foreach ($result->rows() as $row) {
    echo $row[0], PHP_EOL;
}

Laravel 9 / 10 / 11 composer require erikwang2013/bigdata-php
php artisan vendor:publish --tag=bigdata-config // bootstrap/providers.php (Laravel 11)
return [
    Erikwang2013\BigData\Integration\Laravel\BigDataServiceProvider::class,
];

$trino = app(\Erikwang2013\BigData\Integration\Manager::class)->driver('trino');
